//! The `ctype` extension: `php-src/ext/ctype` as one crate under `ext/`
//! (ADR-0004). One dependency, the facade; one entry, `extension()`.
#![forbid(unsafe_code)]
// The `expect` fence is read by `xtask witness`, not by rustdoc (design §8).
#![allow(rustdoc::invalid_codeblock_attributes)]

use php_ext::abi::{Extension, ExtensionBuilder};

/// The extension value (design §7.1), with a witness whose snippet ends in
/// a fatal: php exits 255, which `xtask witness --accept --item extension`
/// wrote onto the fence line, a run narrowed to the item that writes no
/// reading of the crate.
///
/// ```php
/// ctype_digit();
/// ```
/// ```expect exit=255
/// Fatal error: Uncaught ArgumentCountError: ctype_digit() expects exactly 1 argument, 0 given in %s:%d
/// ```
pub fn extension() -> Extension {
    ExtensionBuilder::new("ctype").build()
}
